export default function Dashboard({ownerName,ownerId}:{ownerName:string;ownerId:string}){
 const CACHE='cartao-plus-next-cache-v2:'+ownerId,QUEUE='cartao-plus-next-pending-v2:'+ownerId;
 const [state,setState]=useState<RecordData>(null),[screen,setScreen]=useState('overview'),[active,setActive]=useState(''),[status,setStatus]=useState('Carregando dados…'),[error,setError]=useState(''),[filter,setFilter]=useState('all'),[search,setSearch]=useState(''),[personFilter,setPersonFilter]=useState(''),[sort,setSort]=useState('date'),[modal,setModal]=useState<RecordData>(null),[audit,setAudit]=useState<RecordData[]>([]),[preview,setPreview]=useState<RecordData>(null),[busy,setBusy]=useState(false),[limit,setLimit]=useState(40),[mobile,setMobile]=useState(false),[reviewStatus,setReviewStatus]=useState('pending'),[reviewFocus,setReviewFocus]=useState(''),[cardFilter,setCardFilter]=useState(''),[detailPerson,setDetailPerson]=useState(''),[copied,setCopied]=useState(false);
 const stateRef=useRef<RecordData>(null),queueRef=useRef<RecordData[]>([]),saving=useRef(false),retry=useRef<ReturnType<typeof setTimeout>|null>(null);
 function display(value:RecordData){stateRef.current=value;setState(value);localStorage.setItem(CACHE,JSON.stringify(value))}
 async function load(){try{const r=await fetch('/api/workspace',{cache:'no-store'}),data:RecordData=await r.json();if(!r.ok)throw Error(data.error||'Não foi possível carregar.');let next=data.state;for(const item of queueRef.current){if(item.operation.type==='import'&&next.invoices.some((i:RecordData)=>i.id===item.operation.invoice.id))continue;next=applyOperation(next,item.operation)}const reconciled=reconcileRefunds(next);if(JSON.stringify(reconciled)!==JSON.stringify(next)){queueRef.current.push({requestId:crypto.randomUUID(),operation:{type:'reconcile-refunds'}});localStorage.setItem(QUEUE,JSON.stringify(queueRef.current));next=reconciled}display(next);setAudit(data.history||[]);setActive(previous=>previous||next.activeInvoiceId||next.invoices[0]?.id||'');setStatus(queueRef.current.length?'Alterações pendentes':'Tudo salvo na nuvem');if(queueRef.current.length)await flush()}catch(e){setError((e as Error).message);setStatus('Sem conexão · dados locais preservados')}}
 async function flush(){if(saving.current)return;saving.current=true;let rejected=false;try{while(queueRef.current.length){const item=queueRef.current[0];setStatus('Salvando na nuvem…');const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(item)});const data:RecordData=await r.json();if(!r.ok){if(r.status===400){rejected=true;queueRef.current.shift();localStorage.setItem(QUEUE,JSON.stringify(queueRef.current));try{const latest=await fetch('/api/workspace',{cache:'no-store'}),fresh:RecordData=await latest.json();if(latest.ok){let corrected=fresh.state;for(const pending of queueRef.current)corrected=applyOperation(corrected,pending.operation);display(corrected)}}catch{}}throw Error(data.error||'Falha ao salvar.')}queueRef.current.shift();localStorage.setItem(QUEUE,JSON.stringify(queueRef.current));let next=data.state;for(const pending of queueRef.current){if(pending.operation.type==='import'&&next.invoices.some((i:RecordData)=>i.id===pending.operation.invoice.id))continue;next=applyOperation(next,pending.operation)}display(next)}setStatus('Tudo salvo na nuvem');setError('')}catch(e){setStatus(rejected?'Alteração não salva · confira o aviso':'Salvo neste aparelho · sincronização pendente');setError((e as Error).message);if(queueRef.current.length)retry.current=setTimeout(()=>flush(),5000)}finally{saving.current=false}}
 function act(operation:RecordData){try{if(['allocate','link-card','process'].includes(operation.type))operation={...operation,editId:crypto.randomUUID(),at:new Date().toISOString()};const next=applyOperation(stateRef.current,operation);const request={requestId:crypto.randomUUID(),operation};queueRef.current.push(request);localStorage.setItem(QUEUE,JSON.stringify(queueRef.current));display(next);setStatus('Salvo neste aparelho · sincronizando…');void flush();return true}catch(e){setError((e as Error).message);return false}}
 useEffect(()=>{try{queueRef.current=JSON.parse(localStorage.getItem(QUEUE)||'[]');const cached=JSON.parse(localStorage.getItem(CACHE)||'null');if(cached){stateRef.current=cached;setState(cached);setActive(cached.activeInvoiceId||cached.invoices[0]?.id||'')}}catch{}void load();const online=()=>{void load()};window.addEventListener('online',online);const timer=setInterval(()=>{if(!document.hidden&&!saving.current&&!queueRef.current.length)void load()},30000);return()=>{window.removeEventListener('online',online);clearInterval(timer);if(retry.current)clearTimeout(retry.current)}},[]);
 useEffect(()=>{if(!modal)return;const previous=document.activeElement as HTMLElement|null;const dialog=document.querySelector('.modal') as HTMLElement|null;const first=dialog?.querySelector('input,select,button') as HTMLElement|null;first?.focus();const keyboard=(event:KeyboardEvent)=>{if(event.key==='Escape')setModal(null);if(event.key==='Tab'){const elements=Array.from(dialog?.querySelectorAll<HTMLElement>('button,input,select')||[]).filter(e=>!e.hasAttribute('disabled'));const start=elements[0],end=elements.at(-1);if(event.shiftKey&&document.activeElement===start){event.preventDefault();end?.focus()}else if(!event.shiftKey&&document.activeElement===end){event.preventDefault();start?.focus()}}};document.addEventListener('keydown',keyboard);return()=>{document.removeEventListener('keydown',keyboard);previous?.focus()}},[modal?.type]);
 const invoice=state?.invoices.find((i:RecordData)=>i.id===active)||state?.invoices[0],totals=invoiceTotals(invoice||{transactions:[],carryCents:0,officialCents:0});
 const nav=[['overview','Visão geral',LayoutDashboard],['review','Conferência',CheckCircle2],['transactions','Compras',Receipt],['people','Pessoas',Users],['portal','Portal das Faturas',Users],['payments','Pagamentos',CheckCircle2],['alerts','Alertas de revisão',AlertCircle],['forecast','Próximas parcelas',CreditCard],['closings','Meses fechados',History],['cards','Cartões',CreditCard],['import','Importar fatura',Upload],['audit','Histórico de alterações',History]] as const;
 function go(value:string){setReviewFocus('');setScreen(value);setMobile(false);setLimit(40);setError('');if(value==='audit')void load()}
 function owner(t:RecordData){return shares(t).map((a:RecordData)=>state.people.find((p:RecordData)=>p.id===a.personId)?.name||'Pessoa').join(', ')||'Sem responsável'}
 function matches(t:RecordData){const assigned=shares(t).some((a:RecordData)=>a.amountCents!==0),hasCard=state.cards.some((c:RecordData)=>c.id===t.cardId);if(filter==='unassigned'&&assigned||filter==='no-card'&&(hasCard||assigned)||filter==='processed'&&!t.processed||filter==='installments'&&t.totalInstallments<=1)return false;if(personFilter&&!shares(t).some((a:RecordData)=>a.personId===personFilter))return false;const card=state.cards.find((c:RecordData)=>c.id===t.cardId);return normalize(t.name+' '+owner(t)+' '+(card?.last4||'')+' '+money(t.amountCents)).includes(normalize(search))}
 const review=invoice?invoiceReview(invoice):null;
 const rows=invoice?.transactions.filter(matches).sort((a:RecordData,b:RecordData)=>sort==='value'?effective(b)-effective(a):b.date.localeCompare(a.date)||a.sourceIndex-b.sourceIndex)||[],regular=rows.filter((t:RecordData)=>t.amountCents>0&&!t.compensationRole&&!t.refundSettled),credits=rows.filter((t:RecordData)=>t.amountCents<0&&!t.compensationRole),history=rows.filter((t:RecordData)=>t.compensationRole),refundedRows=rows.filter((t:RecordData)=>t.amountCents>0&&t.refundSettled);
 const needsAllocation=(t:RecordData)=>shares(t).reduce((sum:number,a:RecordData)=>sum+a.amountCents,0)!==effective(t);
 const reviewable=(invoice?.transactions||[]).filter((t:RecordData)=>!t.compensationRole&&!t.refundSettled&&t.amountCents!==0);
 const pendingRows=reviewable.filter((t:RecordData)=>!t.processed||needsAllocation(t));
 const visibleReview=reviewable.filter((t:RecordData)=>{if(reviewFocus&&t.id!==reviewFocus)return false;if(reviewStatus==='pending'&&t.processed&&!needsAllocation(t)||reviewStatus==='unassigned'&&!needsAllocation(t)||reviewStatus==='unchecked'&&t.processed||reviewStatus==='processed'&&(!t.processed||needsAllocation(t)))return false;if(cardFilter&&t.cardId!==cardFilter)return false;if(personFilter&&!shares(t).some((a:RecordData)=>a.personId===personFilter))return false;const card=state.cards.find((c:RecordData)=>c.id===t.cardId);return normalize(t.name+' '+owner(t)+' '+(card?.last4||'')+' '+money(t.amountCents)+' '+(Math.abs(t.amountCents)/100).toFixed(2).replace('.',',')).includes(normalize(search))}).sort((a:RecordData,b:RecordData)=>Number(a.amountCents<0)-Number(b.amountCents<0)||Math.abs(b.amountCents)-Math.abs(a.amountCents));
 const showCarry=false;
 function personBreakdown(id:string){let purchases=0,credits=0;for(const t of invoice.transactions){for(const a of shares(t).filter((a:RecordData)=>a.personId===id)){if(a.amountCents>=0)purchases+=a.amountCents;else credits+=a.amountCents}}return{purchases,credits,carry:(invoice.carryAllocations||[]).filter((a:RecordData)=>a.personId===id).reduce((sum:number,a:RecordData)=>sum+a.amountCents,0)}}
 const alerts=invoice&&state?reviewAlerts(invoice,state):[],forecast=invoice?installmentForecast(invoice):[],lastEdit=invoice?.undoLog?.filter((e:RecordData)=>!e.undoneAt).at(-1);
 function paymentForm(personId:string){setModal({type:'payment',personId,amount:'',date:new Date().toLocaleDateString('en-CA',{timeZone:'America/Bahia'}),method:'Pix',note:''})}
 function reviewTable(){return <section className="panel review-table-panel"><div className="panel-heading"><div><h2>O que precisa ser conferido</h2><p>{visibleReview.length} lançamentos neste filtro · maiores valores primeiro; créditos ao final.</p></div><span className="pending-count">{visibleReview.length} lançamentos</span></div><div className="review-table-scroll" tabIndex={0} role="region" aria-label="Tabela de pendências, deslize para ver todas as colunas"><table className="review-table"><caption className="sr-only">Lançamentos ainda não processados ou com distribuição incompleta</caption><thead><tr><th scope="col">Compra / data</th><th scope="col">Cartão / parcela</th><th scope="col">Responsável</th><th scope="col">Valor</th><th scope="col">Pendência</th><th scope="col">Ações</th></tr></thead><tbody>{visibleReview.map((t:RecordData)=>{const card=state.cards.find((c:RecordData)=>c.id===t.cardId),incomplete=shares(t).reduce((sum:number,a:RecordData)=>sum+a.amountCents,0)!==effective(t);return <tr key={t.id} className={t.amountCents<0?'review-credit':t.amountCents>=10000?'review-high':''}><td data-label="Compra"><b>{t.name}</b><small>{t.date.split('-').reverse().join('/')}</small>{refundInfo(state,invoice,t)&&<small className="green-text">{t.amountCents>0?'Após estorno: '+money(refundInfo(state,invoice,t)?.remaining||0):'Estorno vinculado à compra original'}</small>}</td><td data-label="Cartão"><select aria-label={'Cartão de '+t.name} disabled={invoice.closed} value={t.cardId||''} onChange={e=>act({type:'link-card',invoiceId:invoice.id,transactionId:t.id,cardId:e.target.value})}><option value="">Sem cartão</option>{state.cards.map((c:RecordData)=><option key={c.id} value={c.id}>{c.name} · {c.last4}</option>)}</select><small>{channels[t.channel]||'Compra'}{t.totalInstallments>1?' · Parcela '+t.installment+' de '+t.totalInstallments:''}</small></td><td data-label="Responsável">{shares(t).length>1?<button className="secondary" disabled={invoice.closed} onClick={()=>setModal({type:'allocation',transaction:t,selected:shares(t).map((a:RecordData)=>a.personId),custom:false})}>Editar rateio · {shares(t).length} pessoas</button>:<select aria-label={'Responsável por '+t.name} disabled={invoice.closed} value={shares(t)[0]?.personId||''} onChange={e=>{if(e.target.value)act({type:'allocate',invoiceId:invoice.id,transactionId:t.id,allocations:[{personId:e.target.value,amountCents:t.amountCents}]})}}><option value="" disabled>Escolher responsável</option>{state.people.map((p:RecordData)=><option key={p.id} value={p.id}>{p.name}</option>)}</select>}</td><td data-label="Valor" className="review-money">{money(t.amountCents)}</td><td data-label="Situação"><div className="review-status">{!t.processed&&<span className="status-check">Para conferir</span>}{incomplete&&<span className="status-owner">{shares(t).length?'Rateio incompleto':'Sem responsável'}</span>}{t.processed&&!incomplete&&<span className="status-done">Processada</span>}</div></td><td data-label="Ações"><div className="review-actions"><button className="secondary" disabled={invoice.closed} onClick={()=>setModal({type:'allocation',transaction:t,selected:shares(t).map((a:RecordData)=>a.personId),custom:false})}>Ratear</button><button className="secondary" aria-label={'Vincular cartão a '+t.name} disabled={invoice.closed} onClick={()=>setModal({type:'link',transaction:t,cardId:t.cardId||''})}><CreditCard size={17}/></button><button className={t.processed?'secondary':'primary'} disabled={invoice.closed||incomplete} title={incomplete?'Distribua todo o valor antes de processar':undefined} onClick={()=>act({type:'process',invoiceId:invoice.id,transactionId:t.id,value:!t.processed})}><Check size={17}/>{t.processed?'Reabrir conferência':'Processar'}</button></div></td></tr>})}{!visibleReview.length&&!showCarry&&<tr><td colSpan={6} className="empty">Nenhum lançamento neste filtro. Escolha outro filtro para continuar.</td></tr>}</tbody></table></div>{totals.difference!==0&&<div className="review-difference"><AlertCircle size={18}/><span>O total ainda tem uma diferença de <b>{money(totals.difference)}</b>. Confira a composição antes de fechar o mês.</span><button className="secondary" disabled={invoice.closed} onClick={()=>setModal({type:'invoice',official:(invoice.officialCents/100).toFixed(2),carry:(invoice.carryCents/100).toFixed(2)})}>Ver composição</button></div>}</section>}
 function transactionCard(t:RecordData){const linked=refundInfo(state,invoice,t),card=state.cards.find((c:RecordData)=>c.id===t.cardId),suggestion=t.amountCents<0?refundSuggestion(t,invoice,state):null;return <article className={'transaction '+(t.amountCents<0?'credit ':'')+(t.amountCents>=10000?'high ':'')+(t.compensationRole?'historical ':'')} key={t.id}><div className="tx-main"><div className="tx-icon">{t.amountCents<0?<ArrowDownRight size={20}/>:<Receipt size={20}/>}</div><div className="tx-description"><h3>{t.name}</h3><div className="tx-tags"><span>{t.date.split('-').reverse().join('/')}</span><span>{channels[t.channel]||'Compra'}{card?' · '+card.last4:t.sourceLast4?' · '+t.sourceLast4:''}</span>{t.totalInstallments>1&&<span className="tag purple">Parcela {t.installment} de {t.totalInstallments}</span>}{t.compensationRole&&<span className="tag">Compensada · não soma</span>}{t.amountCents>=10000&&!t.compensationRole&&<span className="tag amber">Valor alto</span>}</div></div><div className="tx-value"><strong>{money(t.amountCents)}</strong>{t.compensationRole?<small>Cobrado: R$ 0,00</small>:<small>{t.amountCents<0?'Desconto':'Cobrado neste mês'}</small>}</div></div>{linked&&<div className="refund-link"><CheckCircle2 size={18}/><div>{t.amountCents>0?<><b>{linked.remaining===0?'Estornada integralmente':'Estorno parcial'} · saldo líquido {money(linked.remaining||0)}</b><small>Devolvido: {money(linked.refunded)} · compra e créditos preservados na fatura.</small></>:<><b>Estorno vinculado a {linked.original?.name}</b><small>Compra de {linked.original?.date.split('-').reverse().join('/')}. Este desconto entra uma única vez.</small></>}</div></div>}{!t.compensationRole&&!t.refundSettled&&<><div className="tx-bottom"><div className="owner-pills">{shares(t).length?shares(t).map((a:RecordData)=><span key={a.personId} className="owner-pill">{state.people.find((p:RecordData)=>p.id===a.personId)?.name} <b>{money(a.amountCents)}</b></span>):<span className="unassigned-pill">Sem responsável</span>}</div><div className="tx-actions"><button disabled={invoice.closed} onClick={()=>setModal({type:'allocation',transaction:t,selected:shares(t).map((a:RecordData)=>a.personId),custom:false})}>{shares(t).length>1?'Editar rateio':'Direcionar / ratear'}</button><button title="Vincular um cartão" disabled={invoice.closed} onClick={()=>setModal({type:'link',transaction:t,cardId:t.cardId||''})}><CreditCard size={15}/></button>{t.amountCents!==0&&<button className={t.processed?'processed':''} disabled={invoice.closed} onClick={()=>act({type:'process',invoiceId:invoice.id,transactionId:t.id,value:!t.processed})}><Check size={15}/>{t.processed?'Processada':'Conferir'}</button>}</div></div>{suggestion&&!linked&&<div className="suggestion"><span>Origem sugerida: <b>•••• {suggestion.card.last4} · {suggestion.person?.name||suggestion.card.name}</b> <small>{suggestion.basis}</small></span>{suggestion.person&&<button disabled={invoice.closed} onClick={()=>setModal({type:'allocation',transaction:t,selected:[suggestion.person.id],custom:false})}>Revisar responsável</button>}</div>}</>}{t.amountCents<0&&!t.compensationRole&&!linked&&<button className="secondary refund-review" disabled={invoice.closed} onClick={()=>setModal({type:'refund',transaction:t,purchaseKey:''})}>Identificar compra deste estorno</button>}</article>}
 function openPerson(id:string){setDetailPerson(id);setCopied(false);go('person-detail')}
 async function copyStatement(text:string){try{await navigator.clipboard.writeText(text);setCopied(true)}catch{setError('Não foi possível copiar automaticamente. Selecione o texto do resumo e copie.')}}
 function downloadBackup(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:2,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}));a.download='CartaoPlus-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(a.href)}
 function exportCSV(){const table=[['Data','Descrição','Cartão','Responsável','Valor original','Valor cobrado','Parcela','Total parcelas'],...invoice.transactions.map((t:RecordData)=>[t.date,t.name,state.cards.find((c:RecordData)=>c.id===t.cardId)?.last4||'',owner(t),(t.amountCents/100).toFixed(2),(effective(t)/100).toFixed(2),t.installment,t.totalInstallments])];const csv='\uFEFF'+table.map((row:RecordData[])=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='CartaoPlus-'+invoice.month+'.csv';a.click();URL.revokeObjectURL(a.href)}
 async function importRegistrations(file:File){setBusy(true);setError('');try{const data=JSON.parse(await file.text());if(data.schema!==2||!Array.isArray(data.people)||!Array.isArray(data.cards))throw Error('Selecione o JSON de cadastros de pessoas e cartões.');const people=data.people,cards=data.cards;if(!people.length&&!cards.length)throw Error('O arquivo não contém cadastros.');const existingPeople=new Set(stateRef.current.people.map((p:RecordData)=>p.id)),existingCards=new Set(stateRef.current.cards.map((c:RecordData)=>c.id)),existingDigits=new Set(stateRef.current.cards.map((c:RecordData)=>c.last4));const newPeople=people.filter((p:RecordData)=>!existingPeople.has(p.id)).length,newCards=cards.filter((c:RecordData)=>!existingCards.has(c.id)&&!existingDigits.has(c.last4)).length;if(!confirm('Importar '+newPeople+' pessoa(s) e '+newCards+' cartão(ões)? Cadastros existentes e faturas serão preservados.'))return;if(act({type:'import-registrations',people,cards}))setStatus('Cadastros importados · sincronizando…')}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 async function importFile(file:File){setBusy(true);setError('');try{if(file.name.toLowerCase().endsWith('.json')){const data=JSON.parse(await file.text()),invoices=data.state?.invoices;if(!Array.isArray(invoices)||!invoices.length)throw Error('O backup não contém faturas para restaurar.');setPreview({...invoices[0],id:crypto.randomUUID(),source:'Backup · '+file.name,backupState:data.state});return}setPreview(await readPDF(file,state.cards,state.people))}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 function importPreview(){if(!preview)return;if(!preview.backupState&&preview.officialCents===null){setError('Informe o total oficial da fatura.');return}if(preview.backupState){if(!confirm('Restaurar este backup na nova versão? Um backup dos dados atuais será baixado antes de substituir.'))return;downloadBackup();if(act({type:'restore',state:preview.backupState})){setActive(preview.backupState.activeInvoiceId);setPreview(null);setScreen('overview')}return}if(act({type:'import',invoice:preview})){setActive(preview.id);setPreview(null);setScreen('overview')}}
 function saveModal(e:React.FormEvent){e.preventDefault();if(modal.type==='refund'){const [purchaseInvoiceId,purchaseId]=modal.purchaseKey.split('|');if(act({type:'link-refund',invoiceId:invoice.id,transactionId:modal.transaction.id,purchaseInvoiceId,purchaseId}))setModal(null)}else if(modal.type==='payment'){try{if(act({type:'payment',invoiceId:invoice.id,payment:{id:crypto.randomUUID(),personId:modal.personId,amountCents:cash(modal.amount),date:modal.date,method:modal.method,note:modal.note}}))setModal(null)}catch(e){setError((e as Error).message)}}else if(modal.type==='allocation'){const selected=modal.selected||[];let allocations;try{allocations=modal.custom?selected.map((personId:string)=>({personId,amountCents:Math.sign(modal.transaction.amountCents)*Math.abs(cash(modal.values?.[personId]||'0'))})):splitCents(modal.transaction.amountCents,selected)}catch(e){setError((e as Error).message);return}if(allocations.reduce((s:number,a:RecordData)=>s+a.amountCents,0)!==modal.transaction.amountCents){setError('O rateio precisa fechar exatamente no valor do lançamento.');return}if(act({type:'allocate',invoiceId:invoice.id,transactionId:modal.transaction.id,allocations}))setModal(null)}else if(modal.type==='person'){if(act({type:'person',person:{id:modal.person?.id||crypto.randomUUID(),name:modal.name}}))setModal(null)}else if(modal.type==='card'){if(act({type:'card',card:{id:modal.card?.id||crypto.randomUUID(),name:modal.name,last4:modal.last4,kind:modal.kind,ownerPersonId:modal.ownerPersonId||''}}))setModal(null)}else if(modal.type==='link'){if(act({type:'link-card',invoiceId:invoice.id,transactionId:modal.transaction.id,cardId:modal.cardId}))setModal(null)}else if(modal.type==='invoice'){if(act({type:'invoice-settings',invoiceId:invoice.id,officialCents:cash(modal.official),carryCents:cash(modal.carry)}))setModal(null)}}
 if(!state)return <main className="loading"><div className="brand-mark">C+</div><h1>Cartão Plus</h1><p>{status}</p>{error&&<p role="alert">{error}</p>}<button onClick={()=>void load()}>Tentar novamente</button></main>;
 if(!invoice)return <main className="loading"><div className="brand-mark">C+</div><h1>Cartão Plus</h1><p>Seu espaço financeiro está pronto e conectado à nuvem.</p><p>Para começar, importe uma fatura em PDF ou restaure um backup JSON do Cartão Plus.</p><label className="primary upload-label" style={{display:'inline-flex',alignItems:'center',gap:8,marginTop:16}}><Upload size={18}/>{busy?'Lendo arquivo…':'Importar fatura ou restaurar backup'}<input type="file" accept="application/pdf,application/json,.pdf,.json" disabled={busy} onChange={e=>{if(e.target.files?.[0])void importFile(e.target.files[0]);e.target.value=''}}/></label>{error&&<p role="alert">{error}</p>}{preview&&<section className="panel preview-panel" style={{width:'min(640px,92vw)',marginTop:24,textAlign:'left'}}><h2>{preview.backupState?'Restaurar backup':'Conferir fatura antes de importar'}</h2><p>{preview.source}</p>{preview.backupState?<p>{preview.backupState.invoices.length} fatura(s) no backup. A restauração substituirá os dados atuais após sua confirmação.</p>:<div className="preview-fields"><label>Mês da fatura<input type="month" value={preview.month} onChange={e=>setPreview({...preview,month:e.target.value})}/></label><label>Total oficial<input defaultValue={preview.officialCents===null?'':(preview.officialCents/100).toFixed(2)} onBlur={e=>setPreview({...preview,officialCents:cash(e.target.value)})}/></label><p>{preview.transactions.length} lançamento(s) identificados</p></div>}<button className="primary" onClick={importPreview}><Check size={17}/>{preview.backupState?'Restaurar backup':'Confirmar importação'}</button><button onClick={()=>setPreview(null)} style={{marginLeft:12}}>Cancelar</button></section>}<label className="secondary upload-label" style={{display:'inline-flex',alignItems:'center',gap:8,marginTop:12}}><Upload size={16}/>{busy?'Lendo arquivo…':'Importar cartões e pessoas (JSON)'}<input type="file" accept="application/json,.json" disabled={busy} onChange={e=>{if(e.target.files?.[0])void importRegistrations(e.target.files[0]);e.target.value=''}}/></label><p style={{marginTop:24}}>{status}</p><button onClick={()=>void load()}>Atualizar dados</button></main>;
 return <div className="shell"><aside className={'sidebar '+(mobile?'open':'')}><a className="brand" href="/"><span className="brand-mark">C+</span><div>Cartão<span>Plus</span><small>CLAREZA EM CADA CENTAVO</small></div></a><div className="workspace-badge"><span className="workspace-dot"/>Meu espaço financeiro<ChevronDown size={15}/></div><small className="nav-label">ORGANIZAÇÃO</small><nav>{nav.map(([id,title,Icon])=><button key={id} onClick={()=>go(id)} className={screen===id?'active':''}><Icon size={19}/>{title}{id==='review'&&<em>{pendingRows.length}</em>}{id==='transactions'&&<em>{invoice.transactions.filter((t:RecordData)=>!t.compensationRole&&t.amountCents>0&&!shares(t).length).length}</em>}</button>)}<a href="/convites" style={{display:'flex',alignItems:'center',gap:10,padding:'12px 16px',textDecoration:'none'}}><Users size={19}/>Gerenciar convites</a></nav><div className="sidebar-footer"><ShieldCheck size={18}/><div>Espaço privado<small>Dados protegidos por sua conta</small></div></div><div className="account"><div className="avatar">L</div><div><b>{ownerName.split(' ')[0]}</b><small>Administradora</small></div></div></aside><main className="main"><header className="topbar"><button className="menu-button" onClick={()=>setMobile(!mobile)} aria-label="Abrir menu"><Menu/></button><div className="breadcrumb">Meu espaço <span>/</span> {screen==='person-detail'?'Detalhamento por pessoa':nav.find(n=>n[0]===screen)?.[1]}</div><div className={'sync '+(status.includes('nuvem')&&!status.includes('Salvando')?'saved':'')} title={status}>{status.includes('pendente')?<WifiOff size={14}/>:<CheckCircle2 size={14}/>}<span>{status}</span></div><button className="icon-button" onClick={downloadBackup} title="Baixar backup completo"><Download size={17}/></button></header><div className="content">{error&&<div className="error-box" role="alert"><AlertCircle size={17}/>{error}<button onClick={()=>setError('')} aria-label="Fechar aviso"><X size={15}/></button></div>}{lastEdit&&!invoice.closed&&<div className="undo-banner" role="status"><span>Última edição: <b>{lastEdit.name}</b></span><button className="secondary" onClick={()=>act({type:'undo-edit',invoiceId:invoice.id,editId:lastEdit.id,at:new Date().toISOString()})}>Desfazer</button></div>}<div className="page-heading"><div><div className="eyebrow">CONTROLE, SEM COMPLICAÇÃO</div><h1>{screen==='overview'?'Seu mês, em ordem.':screen==='person-detail'?'Conta por pessoa':nav.find(n=>n[0]===screen)?.[1]}</h1><p>{screen==='overview'?'Uma visão clara de quanto foi cobrado e de quem é cada valor.':screen==='review'?'Escolha responsável e cartão na linha. Use o rateio para dividir uma compra.':screen==='transactions'?'Direcione compras, confira parcelas e acompanhe os descontos.':'Tudo organizado em um único lugar.'}</p></div><div className="heading-actions"><select aria-label="Escolher fatura" value={invoice.id} onChange={e=>setActive(e.target.value)}>{state.invoices.map((i:RecordData)=><option key={i.id} value={i.id}>{labelMonth(i.month)}</option>)}</select>{screen==='overview'||screen==='transactions'?<button className="primary" onClick={()=>go('import')}><Plus size={17}/>Nova fatura</button>:null}</div></div>
{screen==='review'&&<><div className="review-toolbar"><div className="search-box"><Search size={19}/><input aria-label="Buscar na conferência" placeholder="Buscar compra, pessoa, cartão ou valor" value={search} onChange={e=>setSearch(e.target.value)}/></div><select aria-label="Pessoa na conferência" value={personFilter} onChange={e=>setPersonFilter(e.target.value)}><option value="">Todas as pessoas</option>{state.people.map((p:RecordData)=><option key={p.id} value={p.id}>{p.name}</option>)}</select><select aria-label="Cartão na conferência" value={cardFilter} onChange={e=>setCardFilter(e.target.value)}><option value="">Todos os cartões</option>{state.cards.map((c:RecordData)=><option key={c.id} value={c.id}>{c.name} · {c.last4}</option>)}</select><button className="secondary" onClick={()=>{setSearch('');setPersonFilter('');setCardFilter('');setReviewStatus('pending');setReviewFocus('')}}>Limpar filtros</button></div><div className="filter-tabs">{[['pending','Pendentes'],['unassigned','Sem responsável / rateio'],['unchecked','Para conferir'],['processed','Processadas'],['all','Todas']].map(([id,label])=><button key={id} className={reviewStatus===id?'active':''} onClick={()=>{setReviewStatus(id);setReviewFocus('')}}>{label}</button>)}</div>{invoice.closed&&<div className="note"><ShieldCheck size={20}/><p>Fatura fechada. Reabra na visão geral para editar.</p></div>}{reviewTable()}</>}
{screen==='overview'&&<><section className={'closure-panel '+(invoice.closed?'closed':'')}><div><b>{invoice.closed?'Fatura fechada':'Conferência para fechar o mês'}</b><p>{invoice.closed?'Alterações financeiras bloqueadas. Reabra para corrigir algum valor.':review?.canClose?'Tudo conferido. Você pode fechar esta fatura.':'Confira as pendências antes de fechar.'}</p></div><button className={invoice.closed?'secondary':'primary'} disabled={!invoice.closed&&!review?.canClose} onClick={()=>{if(invoice.closed){if(confirm('Reabrir esta fatura para edição? A reabertura ficará no histórico.'))act({type:'reopen',invoiceId:invoice.id,at:new Date().toISOString()})}else if(confirm('Fechar a fatura e bloquear alterações? Você poderá reabri-la pelo histórico.'))act({type:'close',invoiceId:invoice.id,at:new Date().toISOString()})}}>{invoice.closed?'Reabrir fatura':'Fechar mês'}</button>{!invoice.closed&&<div className="closure-checks"><span className={review?.difference===0?'ok':''}>Total oficial: {review?.difference===0?'confere':money(review?.difference||0)+' de diferença'}</span><span className={review?.unassignedCount===0?'ok':''}>{review?.unassignedCount} lançamentos sem distribuição completa</span><span className={review?.uncheckedCount===0?'ok':''}>{review?.uncheckedCount} lançamentos para conferir</span><span className={review?.carryPending===0?'ok':''}>Diferença do pagamento anterior: {money(review?.carryPending||0)}</span></div>}</section><div className="kpi-grid"><article className="kpi featured"><span>Total oficial da fatura</span><strong>{money(invoice.officialCents)}</strong><small>{labelMonth(invoice.month)} <CreditCard size={20}/></small></article><article className="kpi"><span>Direcionado às pessoas</span><strong>{money(totals.allocated)}</strong><small>{state.people.length} pessoas cadastradas</small></article><article className="kpi"><span>Ainda para distribuir</span><strong className="amber-text">{money(totals.unassigned)}</strong><small>Somente compras e créditos sem responsável</small></article></div><section className="review-callout"><div className="review-callout-icon"><CheckCircle2 size={29}/></div><div><h2>{pendingRows.length?pendingRows.length+' lançamentos para revisar':'Conferência dos lançamentos concluída'}</h2><p>{review?.canClose?'Tudo pronto para fechar o mês.':review?.carryPending?'Confira os lançamentos e a diferença do pagamento anterior, exibida na composição.':'Distribua os valores e confirme cada lançamento na tela de conferência.'}</p></div><button className="primary" onClick={()=>{setSearch('');setPersonFilter('');setCardFilter('');setReviewStatus('pending');go('review')}}>Abrir conferência <ArrowUpRight size={18}/></button></section><div className="overview-grid"><section className="panel"><div className="panel-heading"><div><h2>Quanto cada pessoa paga</h2><p>Valores líquidos, com os estornos aplicados uma vez.</p></div><button onClick={()=>go('people')}>Ver pessoas <ArrowUpRight size={16}/></button></div>{personTotals(invoice,state.people).filter((p:RecordData)=>p.count).sort((a:RecordData,b:RecordData)=>b.total-a.total).map((p:RecordData,i:number)=><button className="person-total" key={p.id} onClick={()=>openPerson(p.id)}><span className={'avatar tone-'+i%4}>{p.name.slice(0,1)}</span><div><b>{p.name}</b><small>{p.count} lançamentos</small></div><strong>{money(p.total)}</strong><ArrowUpRight size={16}/></button>)}</section><section className="panel composition"><h2>Composição da fatura</h2><div className="composition-row"><span>Compras e parcelas</span><b>{money(totals.charges)}</b></div><div className="composition-row"><span>Créditos e estornos</span><b className="green-text">{money(totals.credits)}</b></div><div className="composition-row"><span>Diferença do pagamento anterior</span><b>{money(invoice.carryCents)}</b></div>{invoice.carryCents!==0&&<div className="note"><AlertCircle size={19}/><p><b>Valor bancário a conferir, fora do valor para distribuir.</b> É a diferença entre “Fatura anterior” e “Pagamento recebido” no resumo do PDF. Não indica que alguma pessoa ficou devendo. Confira o pagamento ao banco antes de cobrar alguém.</p></div>}<div className="composition-row total"><span>Total apurado</span><b>{money(totals.calculated)}</b></div><div className="composition-row"><span>Diferença a conferir</span><b className="amber-text">{money(totals.difference)}</b></div><div className="note"><ShieldCheck size={19}/><p>Compra original e crédito de parcelamento ficam no histórico. Só a parcela cobrada entra no total.</p></div><button className="wide secondary" onClick={()=>{setFilter('unassigned');setPersonFilter('');go('transactions')}}>Conferir valores sem responsável <ArrowUpRight size={16}/></button><div className="review-progress"><span>{totals.processed} lançamentos conferidos</span><div><i style={{width:Math.min(100,totals.processed/Math.max(1,regular.length)*100)+'%'}}/></div></div></section></div></>}
{screen==='transactions'&&<><div className="toolbar"><div className="search-box"><Search size={18}/><input aria-label="Buscar compras" placeholder="Buscar compra, pessoa, cartão ou valor" value={search} onChange={e=>{setSearch(e.target.value);setLimit(40)}}/></div><select aria-label="Filtrar por pessoa" value={personFilter} onChange={e=>setPersonFilter(e.target.value)}><option value="">Todas as pessoas</option>{state.people.map((p:RecordData)=><option key={p.id} value={p.id}>{p.name}</option>)}</select><select aria-label="Ordenação" value={sort} onChange={e=>setSort(e.target.value)}><option value="date">Mais recentes</option><option value="value">Maior valor</option></select><button className="secondary" onClick={exportCSV}><Download size={16}/>Exportar</button></div><div className="filter-tabs">{[['all','Todas'],['no-card','Sem cartão'],['unassigned','Sem responsável'],['installments','Parceladas'],['processed','Conferidas']].map(([value,label])=><button key={value} className={filter===value?'active':''} onClick={()=>{setFilter(value);setLimit(40)}}>{label}</button>)}</div><div className="list-header"><span>{regular.length} compras encontradas</span><small>Cada linha da fatura é preservada, inclusive as repetidas.</small></div><div className="transaction-list">{regular.slice(0,limit).map(transactionCard)}{!regular.length&&<div className="empty"><CheckCircle2/><h3>Nenhuma compra nesse filtro</h3><p>Altere a busca ou escolha outra aba.</p></div>}</div>{regular.length>limit&&<button className="load-more" onClick={()=>setLimit(limit+40)}>Mostrar mais compras</button>}{refundedRows.length>0&&<section className="settled-refunds"><div className="section-title"><h2>Compras estornadas integralmente</h2><span>{refundedRows.length} compras · saldo R$ 0,00</span></div>{refundedRows.map(transactionCard)}</section>}<section className="credits-section"><div className="section-title"><div><span className="eyebrow">DESCONTOS, SEM DUPLICIDADE</span><h2>Créditos e estornos</h2></div><strong className="green-text">{money(credits.reduce((s:number,t:RecordData)=>s+t.amountCents,0))}</strong></div><p>Direcionar um crédito troca quem recebe o desconto. Não cria um novo abatimento.</p><div className="transaction-list">{credits.map(transactionCard)}{!credits.length&&<div className="empty">Nenhum crédito neste filtro.</div>}</div>{history.length>0&&<details className="history-details"><summary>Compras compensadas por parcelamento · {history.length} registros</summary>{history.map(transactionCard)}</details>}</section></>}
{screen==='person-detail'&&(()=>{const person=state.people.find((p:RecordData)=>p.id===detailPerson);if(!person)return null;const summary=personStatement(invoice,person.id),balance=paymentBalance(invoice,person.id),text=statementText(invoice,person,state.cards);const section=(title:string,entries:RecordData[])=> <section className="panel statement-section"><div className="panel-heading"><h2>{title}</h2><span>{entries.length} lançamentos</span></div><div className="statement-scroll"><table className="statement-table"><thead><tr><th scope="col">Data / compra</th><th scope="col">Cartão / parcela</th><th scope="col">Valor da compra</th><th scope="col">Parte de {person.name}</th><th scope="col">Conferência</th></tr></thead><tbody>{entries.map(t=>{const card=state.cards.find((c:RecordData)=>c.id===t.cardId);return <tr key={t.id}><td><b>{t.name}</b><small>{t.date.split('-').reverse().join('/')}</small></td><td>{card?'•••• '+card.last4:channels[t.channel]||'Sem cartão'}<small>{t.totalInstallments>1?'Parcela '+t.installment+' de '+t.totalInstallments:'À vista'}{t.shared?' · Rateada':''}</small></td><td>{money(t.amountCents)}</td><td className={t.personCents<0?'green-text':''}><strong>{money(t.personCents)}</strong></td><td><div className="person-review-actions"><span className={t.processed?'green-text':''}>{t.processed?'Processada':'Para conferir'}</span><button type="button" className="secondary" onClick={()=>{setSearch('');setPersonFilter('');setCardFilter('');setReviewStatus('all');go('review');setReviewFocus(t.id)}}><Check size={15}/> {t.processed?'Revisar conferência':'Conferir agora'}</button></div></td></tr>})}{!entries.length&&<tr><td colSpan={5} className="empty">Nenhum lançamento atribuído nesta seção.</td></tr>}</tbody></table></div></section>;return <><div className="person-detail-heading"><button className="secondary" onClick={()=>go('people')}>Voltar às pessoas</button><select aria-label="Escolher pessoa" value={person.id} onChange={e=>{setDetailPerson(e.target.value);setCopied(false)}}>{state.people.map((p:RecordData)=><option key={p.id} value={p.id}>{p.name}</option>)}</select><button className="primary" onClick={()=>copyStatement(text)}>{copied?<Check size={18}/>:<Download size={18}/>} {copied?'Resumo copiado':'Copiar resumo para WhatsApp'}</button></div><div className="statement-hero"><div><span className="eyebrow">{invoice.closed?'FATURA FECHADA':'RESUMO PROVISÓRIO · FATURA ABERTA'}</span><h2>{person.name}</h2><p>{labelMonth(invoice.month)} · {summary.pending} lançamentos para conferir</p></div><div><span>Total líquido</span><strong>{money(summary.total)}</strong></div></div><div className="statement-equation"><div><span>Compras e parcelas</span><b>{money(summary.purchaseCents)}</b></div><div><span>Créditos e estornos</span><b className="green-text">{money(summary.creditCents)}</b></div><div><span>Saldo anterior</span><b>{money(summary.carry)}</b></div></div><section className="panel person-payments"><div className="section-title"><h2>Pagamento desta pessoa</h2><button className="primary" onClick={()=>paymentForm(person.id)}>Registrar pagamento</button></div><div className="person-breakdown"><div><span>Recebido</span><b className="green-text">{money(balance.paid)}</b></div><div><span>{balance.credit?'Crédito a favor':'Falta receber'}</span><b>{money(balance.credit||balance.due)}</b></div></div><button className="secondary" onClick={()=>go('payments')}>Ver histórico de pagamentos</button></section>{section('Compras e parcelas',summary.purchases)}{summary.carry!==0&&<div className="note"><History size={20}/><p>Saldo anterior atribuído a {person.name}: <b>{money(summary.carry)}</b>. Este valor já está incluído no total líquido.</p></div>}{section('Créditos e estornos',summary.credits)}<section className="panel statement-copy"><div className="panel-heading"><div><h2>Resumo para enviar</h2><p>Confira o texto e copie para sua conversa no WhatsApp.</p></div></div><textarea aria-label="Resumo para copiar" readOnly value={text} onFocus={e=>e.target.select()}/><button className="primary" onClick={()=>copyStatement(text)}>{copied?'Copiado':'Copiar resumo'}</button><p role="status">{copied?'Texto copiado. Cole na conversa da pessoa.':''}</p></section></>})()}
{screen==='payments'&&<><div className="section-title"><div><h2>Recebimentos por pessoa</h2><p className="notice">Valores desta fatura · {invoice.closed?'fatura fechada':'totais provisórios enquanto a fatura estiver aberta'}</p></div><button className="primary" onClick={()=>paymentForm('')}>Registrar pagamento</button></div><div className="entity-grid">{state.people.map((p:RecordData)=>{const b=paymentBalance(invoice,p.id);return <article className="panel payment-card" key={p.id}><h2>{p.name}</h2><div className="person-breakdown"><div><span>Total líquido</span><b>{money(b.total)}</b></div><div><span>Recebido</span><b className="green-text">{money(b.paid)}</b></div><div><span>{b.credit?'Crédito a favor':'Falta receber'}</span><b className={b.credit?'green-text':'amber-text'}>{money(b.credit||b.due)}</b></div></div><p className="notice">{b.credit?'Pagamento excedente ou saldo credor':b.due?'Pagamento pendente':b.total===0&&b.paid===0?'Sem valor a receber':'Quitado'}</p><button className="primary wide" onClick={()=>paymentForm(p.id)}>Registrar recebimento</button></article>})}</div><section className="panel payment-history"><h2>Histórico de pagamentos</h2>{!(invoice.payments||[]).length&&<p className="empty">Nenhum pagamento registrado.</p>}{(invoice.payments||[]).slice().reverse().map((p:RecordData)=><div className={'payment-item '+(p.voidedAt?'voided':'')} key={p.id}><div><b>{state.people.find((person:RecordData)=>person.id===p.personId)?.name}</b><small>{p.date.split('-').reverse().join('/')} · {p.method}{p.note?' · '+p.note:''}{p.voidedAt?' · Cancelado':''}</small></div><strong>{money(p.amountCents)}</strong>{!p.voidedAt&&<button className="secondary" onClick={()=>{if(confirm('Cancelar este registro de pagamento? O registro será mantido no histórico.'))act({type:'void-payment',invoiceId:invoice.id,paymentId:p.id,at:new Date().toISOString()})}}>Cancelar registro</button>}</div>)}</section></>}
{screen==='alerts'&&<><div className="note"><AlertCircle size={20}/><p>São sugestões para conferir no PDF. Nenhuma compra é apagada e nenhum crédito é abatido novamente ao revisar um alerta.</p></div>{!alerts.length&&<div className="panel empty">Nenhum alerta identificado nesta fatura.</div>}<div className="alert-list">{alerts.map((a:RecordData)=><section className="panel alert-card" key={a.id}><div className="section-title"><h2>{a.title}</h2><span className={a.reviewed?'green-text':'amber-text'}>{a.reviewed?'Revisado':'Para revisar'}</span></div><p className="notice">{a.description}</p>{a.rows.map((t:RecordData)=><div className="alert-row" key={t.id}><div><b>{t.name}</b><small>{t.date.split('-').reverse().join('/')} · {owner(t)}</small></div><strong>{money(t.amountCents)}</strong><button className="secondary" onClick={()=>{setSearch(t.name);setReviewStatus('all');setCardFilter('');setPersonFilter('');go('review')}}>Ver na conferência</button></div>)}{a.kind==='refund'&&<button className="secondary" disabled={invoice.closed} onClick={()=>setModal({type:'refund',transaction:a.rows[0],purchaseKey:''})}>Identificar compra original</button>}{!a.reviewed&&<button className="primary" onClick={()=>act({type:'review-alert',invoiceId:invoice.id,alertId:a.id,at:new Date().toISOString()})}>Marcar alerta como revisado</button>}</section>)}</div></>}
{screen==='forecast'&&<><div className="note"><CreditCard size={20}/><p>Previsão baseada nas parcelas da fatura selecionada, mantendo o valor mensal atual. Não altera as faturas e não inclui compras futuras, juros novos, antecipações ou possíveis estornos.</p></div>{!forecast.length&&<section className="panel empty">Não há parcelas futuras identificadas nesta fatura.</section>}<div className="forecast-list">{forecast.map((m:RecordData)=><details className="panel forecast-month" key={m.month}><summary><span>{labelMonth(m.month)}<small>{m.rows.length} parcelas previstas</small></span><strong>{money(m.total)}</strong></summary>{m.rows.map((t:RecordData)=><div className="forecast-row" key={t.transactionId}><div><b>{t.name}</b><small>Parcela {t.installment} de {t.totalInstallments} · {state.cards.find((c:RecordData)=>c.id===t.cardId)?.last4||'Sem cartão'}</small><small>{t.allocations.length?t.allocations.map((a:RecordData)=>(state.people.find((p:RecordData)=>p.id===a.personId)?.name||'Pessoa')+': '+money(a.amountCents)).join(' · '):'Sem responsável definido'}</small></div><strong>{money(t.amountCents)}</strong></div>)}</details>)}</div></>}
{screen==='closings'&&<><div className="note"><History size={20}/><p>Ao fechar uma fatura, um resumo de cada pessoa fica salvo como era naquele momento. Reabrir a fatura mantém esse registro; fechar novamente cria uma nova versão.</p></div>{!state.invoices.some((i:RecordData)=>i.closings?.length)&&<div className="panel empty">Nenhum resumo de fechamento salvo ainda. Feche uma fatura conciliada na visão geral.</div>}{state.invoices.slice().sort((a:RecordData,b:RecordData)=>b.month.localeCompare(a.month)).flatMap((i:RecordData)=>(i.closings||[]).slice().reverse().map((c:RecordData)=><section className="panel closing-archive" key={c.id}><div className="section-title"><h2>{labelMonth(c.month)}</h2><strong>{money(c.officialCents)}</strong></div><p className="notice">Fechamento em {new Date(c.at).toLocaleString('pt-BR',{timeZone:'America/Bahia'})}</p>{c.people.map((p:RecordData)=><details key={p.personId}><summary><span>{p.name}</span><b>{money(p.total)}</b></summary><pre>{p.text}</pre><button className="secondary" onClick={()=>copyStatement(p.text)}>{copied?'Copiado':'Copiar resumo salvo'}</button></details>)}</section>))}</>}
{screen==='portal'&&<PortalFaturas embedded/>}
{screen==='people'&&<><div style={{marginBottom:16}}><label className="secondary upload-label" style={{display:'inline-flex',alignItems:'center',gap:8,marginTop:12}}><Upload size={16}/>{busy?'Lendo arquivo…':'Importar cartões e pessoas (JSON)'}<input type="file" accept="application/json,.json" disabled={busy} onChange={e=>{if(e.target.files?.[0])void importRegistrations(e.target.files[0]);e.target.value=''}}/></label></div><div className="section-title"><h2>{state.people.length} pessoas cadastradas</h2><button className="primary" onClick={()=>setModal({type:'person',name:''})}><Plus size={16}/>Adicionar pessoa</button></div><div className="entity-grid">{personTotals(invoice,state.people).map((p:RecordData,i:number)=><article className="entity panel" key={p.id}><div className="entity-top"><span className={'avatar tone-'+i%4}>{p.name.slice(0,1)}</span><button onClick={()=>setModal({type:'person',person:p,name:p.name})}>Editar</button></div><h3>{p.name}</h3><strong>{money(p.total)}</strong><div className="person-breakdown"><div><span>Compras e parcelas</span><b>{money(personBreakdown(p.id).purchases)}</b></div><div><span>Créditos e estornos</span><b className="green-text">{money(personBreakdown(p.id).credits)}</b></div><div><span>Saldo anterior</span><b>{money(personBreakdown(p.id).carry)}</b></div></div><p>{p.count} lançamentos · {state.cards.filter((c:RecordData)=>c.ownerPersonId===p.id).length} cartões</p><div className="card-chips">{state.cards.filter((c:RecordData)=>c.ownerPersonId===p.id).map((c:RecordData)=><span key={c.id}>•••• {c.last4}</span>)}</div><button className="wide secondary" onClick={()=>openPerson(p.id)}>Ver detalhamento <ArrowUpRight size={15}/></button></article>)}</div></>}
{screen==='cards'&&<><div style={{marginBottom:16}}><button className="secondary" onClick={()=>{if(confirm('Associar compras ainda sem responsável aos titulares dos cartões identificados pelos quatro últimos dígitos? Rateios existentes e faturas fechadas serão preservados.'))act({type:'associate-card-owners'})}}><CheckCircle2 size={16}/>Associar compras aos titulares dos cartões</button><small style={{display:'block',marginTop:8}}>Somente compras positivas sem rateio e com cartão identificado. Não altera atribuições existentes.</small></div><div style={{marginBottom:16}}><label className="secondary upload-label" style={{display:'inline-flex',alignItems:'center',gap:8,marginTop:12}}><Upload size={16}/>{busy?'Lendo arquivo…':'Importar cartões e pessoas (JSON)'}<input type="file" accept="application/json,.json" disabled={busy} onChange={e=>{if(e.target.files?.[0])void importRegistrations(e.target.files[0]);e.target.value=''}}/></label></div><div className="section-title"><h2>{state.cards.length} cartões cadastrados</h2><button className="primary" onClick={()=>setModal({type:'card',name:'Nubank',last4:'',kind:'virtual',ownerPersonId:''})}><Plus size={16}/>Adicionar cartão</button></div><div className="entity-grid">{state.cards.map((c:RecordData,i:number)=><article className={'bank-card bank-tone-'+i%3} key={c.id}><div><span>{c.kind==='physical'?'FÍSICO':'VIRTUAL'}</span><CreditCard size={26}/></div><h3>{c.name}</h3><strong>•••• &nbsp;{c.last4}</strong><div className="bank-owner"><span>{state.people.find((p:RecordData)=>p.id===c.ownerPersonId)?.name||'Sem responsável'}</span><button onClick={()=>setModal({type:'card',card:c,name:c.name,last4:c.last4,kind:c.kind,ownerPersonId:c.ownerPersonId})}>Editar</button></div></article>)}</div></>}
{screen==='import'&&<><div className="import-panel panel"><div className="upload-icon"><Upload size={30}/></div><h2>Uma fatura nova. Tudo no lugar.</h2><p>Importe o PDF do Nubank e revise antes de salvar. A fatura atual e seus rateios continuam guardados.</p><label className="primary upload-label">{busy?'Lendo a fatura…':'Selecionar PDF ou backup'}<input type="file" accept="application/pdf,application/json,.pdf,.json" disabled={busy} onChange={e=>{if(e.target.files?.[0])void importFile(e.target.files[0]);e.target.value=''}}/></label><small>Leitura feita no seu navegador. PDFs com texto selecionável.</small></div>{preview&&<section className="panel preview-panel"><div className="section-title"><h2>Prévia · {preview.source}</h2><button onClick={()=>setPreview(null)} aria-label="Cancelar prévia"><X/></button></div><div className="preview-fields"><label>Mês da fatura<input type="month" value={preview.month} onChange={e=>setPreview({...preview,month:e.target.value})}/></label><label>Total oficial<input defaultValue={preview.officialCents===null?'':(preview.officialCents/100).toFixed(2)} onBlur={e=>setPreview({...preview,officialCents:cash(e.target.value)})}/></label><label>Diferença do pagamento anterior<input defaultValue={(preview.carryCents/100).toFixed(2)} onBlur={e=>setPreview({...preview,carryCents:cash(e.target.value)})}/></label></div><div className="preview-summary">{preview.transactions.length} linhas preservadas · diferença: <b>{money((preview.officialCents||0)-invoiceTotals(preview).calculated)}</b></div><div className="preview-table"><table><thead><tr><th>Data</th><th>Descrição</th><th>Valor</th></tr></thead><tbody>{preview.transactions.slice(0,25).map((t:RecordData)=><tr key={t.id}><td>{t.date}</td><td>{t.name}</td><td>{money(t.amountCents)}</td></tr>)}</tbody></table></div><button className="primary" onClick={importPreview}><Check size={17}/>Confirmar importação</button></section>}<div className="note import-note"><History size={20}/><p>As 169 linhas de outubro foram preservadas na migração, recuperando três registros que a versão antiga havia eliminado. Os direcionamentos existentes foram mantidos.</p></div></>}
{screen==='audit'&&<section className="panel"><div className="panel-heading"><div><h2>Histórico de alterações</h2><p>Cada salvamento na nuvem recebe um registro. Reenviar a mesma ação não duplica a alteração.</p></div><button onClick={downloadBackup}><Download size={16}/>Backup completo</button></div>{audit.length?audit.map(event=>{let operation:RecordData={};try{operation=JSON.parse(event.operation)}catch{}return <div className="audit-row" key={event.event_id}><span className="audit-dot"/><div><b>{{'reconcile-refunds':'Estornos vinculados automaticamente','link-refund':'Estorno vinculado à compra',payment:'Pagamento recebido','void-payment':'Registro de pagamento cancelado','review-alert':'Alerta revisado','undo-edit':'Edição desfeita',allocate:'Responsável / rateio atualizado',process:'Conferência atualizada',person:'Pessoa salva',card:'Cartão salvo',import:'Fatura importada','link-card':'Cartão vinculado','invoice-settings':'Composição revisada',close:'Fatura fechada',reopen:'Fatura reaberta',restore:'Backup restaurado'}[operation.type as string]||'Dados atualizados'}</b><small>{new Date(event.created_at).toLocaleString('pt-BR')}</small></div><span>Revisão {event.revision}</span></div>}):<div className="empty">Suas próximas alterações aparecerão aqui.</div>}</section>}
<footer className="page-footer"><span>Cartão Plus · nova versão</span><span>Valores em centavos. Histórico preservado.</span></footer></div></main>
{modal&&<div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)setModal(null)}}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-header"><h2 id="modal-title">{modal.type==='refund'?'Vincular estorno à compra':modal.type==='payment'?'Registrar pagamento':modal.type==='allocation'?'Direcionar ou ratear':modal.type==='person'?'Pessoa':modal.type==='card'?'Cartão':modal.type==='invoice'?'Composição da fatura':'Vincular cartão'}</h2><button aria-label="Fechar" onClick={()=>setModal(null)}><X/></button></div><form onSubmit={saveModal}>{modal.type==='refund'&&<><div className="allocation-summary"><span>{modal.transaction.name}</span><strong>{money(modal.transaction.amountCents)}</strong></div><p className="notice">Confira a compra original. Valores iguais sozinhos não confirmam que o estorno pertence à mesma compra. O vínculo preserva o desconto que já existe na fatura.</p><label>Compra correspondente<select required value={modal.purchaseKey} onChange={e=>setModal({...modal,purchaseKey:e.target.value})}><option value="">Escolher compra</option>{refundCandidates(state,invoice,modal.transaction).map((c:RecordData)=><option key={c.invoiceId+'|'+c.transaction.id} value={c.invoiceId+'|'+c.transaction.id}>{c.transaction.date} · {c.transaction.name} · {money(c.transaction.amountCents)} · {c.sameContext?'mesmo cartão/tipo':'cartão/tipo a confirmar'} · {c.availableCents===-modal.transaction.amountCents?'integral':'parcial'}</option>)}</select></label>{!refundCandidates(state,invoice,modal.transaction).length&&<p className="notice">Nenhuma compra compatível pelo nome e valor disponível nas faturas importadas. A compra pode estar em uma fatura anterior ainda não importada.</p>}</>}{modal.type==='payment'&&<><label>Pessoa<select required value={modal.personId} onChange={e=>setModal({...modal,personId:e.target.value})}><option value="">Escolher pessoa</option>{state.people.map((p:RecordData)=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label>Valor recebido (R$)<input required inputMode="decimal" value={modal.amount} onChange={e=>setModal({...modal,amount:e.target.value})}/></label><label>Data<input required type="date" value={modal.date} onChange={e=>setModal({...modal,date:e.target.value})}/></label><label>Forma de pagamento<select value={modal.method} onChange={e=>setModal({...modal,method:e.target.value})}><option>Pix</option><option>Transferência</option><option>Dinheiro</option><option>Outro</option></select></label><label>Observação<input maxLength={500} value={modal.note} onChange={e=>setModal({...modal,note:e.target.value})}/></label><p className="notice">Pagamento recebido da pessoa referente a esta fatura. Ele não altera compras, estornos ou a conferência.</p></>}{modal.type==='allocation'&&<><div className="allocation-summary"><span>{modal.transaction.name}</span><strong>{money(modal.transaction.amountCents)}</strong></div>{modal.transaction.amountCents<0&&<p className="notice">Este é um desconto existente. Ao mudar o responsável, o desconto sai da pessoa anterior e vai para a selecionada.</p>}<div className="filter-tabs"><button type="button" className={!modal.custom?'active':''} onClick={()=>setModal({...modal,custom:false})}>Dividir igualmente</button><button type="button" className={modal.custom?'active':''} onClick={()=>setModal({...modal,custom:true})}>Valores personalizados</button></div><div className="split-list">{state.people.map((p:RecordData)=><label key={p.id} className="split-row"><input type="checkbox" checked={modal.selected.includes(p.id)} onChange={e=>setModal({...modal,selected:e.target.checked?[...modal.selected,p.id]:modal.selected.filter((id:string)=>id!==p.id)})}/><span>{p.name}</span>{modal.custom&&modal.selected.includes(p.id)&&<input aria-label={'Valor de '+p.name} inputMode="decimal" placeholder="0,00" value={modal.values?.[p.id]||''} onChange={e=>setModal({...modal,values:{...modal.values,[p.id]:e.target.value}})}/>}</label>)}</div></>}{modal.type==='person'&&<label>Nome<input required value={modal.name} onChange={e=>setModal({...modal,name:e.target.value})}/></label>}{modal.type==='card'&&<><label>Nome do cartão<input required value={modal.name} onChange={e=>setModal({...modal,name:e.target.value})}/></label><div className="form-grid"><label>Últimos quatro dígitos<input required pattern="[0-9]{4}" maxLength={4} inputMode="numeric" value={modal.last4} onChange={e=>setModal({...modal,last4:e.target.value})}/></label><label>Tipo<select value={modal.kind} onChange={e=>setModal({...modal,kind:e.target.value})}><option value="virtual">Virtual</option><option value="physical">Físico</option></select></label></div><label>Responsável<select value={modal.ownerPersonId} onChange={e=>setModal({...modal,ownerPersonId:e.target.value})}><option value="">Sem responsável</option>{state.people.map((p:RecordData)=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><p className="notice">Cartões físicos e Pix exigem escolher o responsável de cada compra. Um cartão virtual só possui um responsável.</p></>}{modal.type==='link'&&<label>Cartão<select value={modal.cardId} onChange={e=>setModal({...modal,cardId:e.target.value})}><option value="">Sem cartão</option>{state.cards.map((c:RecordData)=><option key={c.id} value={c.id}>{c.name} · {c.last4}</option>)}</select></label>}{modal.type==='invoice'&&<><div className="composition-row"><span>Compras e parcelas</span><b>{money(totals.charges)}</b></div><div className="composition-row"><span>Estornos</span><b>{money(totals.credits)}</b></div><label>Diferença do pagamento anterior no PDF (R$)<input required inputMode="decimal" value={modal.carry} onChange={e=>setModal({...modal,carry:e.target.value})}/></label><label>Total oficial (R$)<input required inputMode="decimal" value={modal.official} onChange={e=>setModal({...modal,official:e.target.value})}/></label><p className="notice">A diferença é exibida para conferência. O sistema nunca cria um ajuste para esconder valores faltantes.</p></>}{error&&<p className="form-error">{error}</p>}<div className="modal-actions"><button type="button" className="secondary" onClick={()=>setModal(null)}>Cancelar</button><button className="primary" type="submit">Salvar</button></div></form></section></div>}
</div>
}
